STORY = [('bu_xiaogu', '按规矩，我应该怎么称呼您？', 'By proper etiquette, how should I address you?', [(275, '按规矩'), (276, '我应该怎么称呼您')], ''), ('bu_xiaogu', '阳子，您好。是淳于先生告诉我您的住处。', 'Hello, Yangzi. Mr Chun Yu told me where to find your home.', [(279, '您好'), (280, '是淳于先生告诉我您的住处')], ''), ('bu_xiaogu', '我只是他的下属。', 'I am simply one of his subordinates.', [(283, '我只是他的下属')], ''), ('bu_xiaogu', '您跟他也是知己？我听说您在这边是为了研究音乐。', 'Are you a kindred spirit of his as well? I heard you settled here to study music.', [(289, '您跟他也是知己'), (290, '我听说您在这边'), (291, '是为了研究音乐')], ''), ('bu_xiaogu', '像您这样的词曲作家，听到您还搞音乐，真的是令人期待。', 'Hearing that a songwriter like you is still creating music truly fills people with anticipation.', [(294, '像您这样的词曲作家'), (295, '听到您还搞音乐'), (296, '真的是令人期待')], ''), ('bu_xiaogu', '我知道您对俗事不在乎，您做音乐只是为了音乐本身。', "I know you care nothing for worldly affairs and make music purely for music's sake.", [(297, '我知道您对俗事不在乎'), (298, '您做音乐只是为了音乐本身')], ''), ('bu_xiaogu', '可是前几年您与白石公司签订了一份合约，按照法律来讲，对您的权益是有所损害的。', 'Yet a few years ago you signed a contract with Baishi that legally infringed upon your own rights.', [(299, '可是前几年'), (300, '签订了一份合约'), (301, '按照法律来讲'), (302, '对您的权益是有所损害的')], ''), ('bu_xiaogu', '如果您愿意出来主张一下，对我们的公司会起到非常大的帮助。', 'If you are willing to step forward and assert your rights, it will help our company immensely.', [(303, '如果您愿意出来主张一下'), (304, '我们的公司'), (305, '大的帮助')], ''), ('bu_xiaogu', '毕竟这些俗事对淳于总还有我们来说，也是抛不开的尘世烦恼。', 'After all, for Mr Chun Yu and the rest of us, these worldly tangles are troubles we cannot simply shake off.', [(306, '毕竟这些俗事'), (307, '对淳于总还有我们来说'), (308, '也是抛不开的'), (308, '烦恼')], ''), ('bu_xiaogu', '真的吗？太谢谢您了！', 'Truly? Thank you so very much!', [(310, '真的吗'), (311, '太谢谢您了')], ''), ('bu_xiaogu', '可是您这么了解他，为什么要离开他？', 'Yet since you understand him so deeply, why did you leave him back then?', [(337, '可是您这么了解他'), (338, '为什么要离开他')], ''), ('bu_xiaogu', '我以为在这儿都得这么说话呢！快走吧，我赶着回上海！', "I thought everyone had to speak in classical poetry around here! Let's hurry — I'm rushing back to Shanghai!", [(347, '我以为在这儿'), (348, '都得这么说话呢'), (349, '快走吧 我赶着回上海')], '')]
WALK = [(0, None, "'By proper etiquette, how should I address you?'"), (1, None, "'Hello, Yangzi. Mr Chun Yu told me where to find your home.'"), (2, None, "'I am simply one of his subordinates.'"), (3, None, "'Are you a kindred spirit of his as well? I heard you settled here to study music.'"), (4, None, "'Hearing that a songwriter like you is still creating music truly fills people with anticipation.'"), (5, None, '"I know you care nothing for worldly affairs and make music purely for music\'s sake."'), (6, None, "'Yet a few years ago you signed a contract with Baishi that legally infringed upon your own rights.'"), (7, None, "'If you are willing to step forward and assert your rights, it will help our company immensely.'"), (8, None, "'After all, for Mr Chun Yu and the rest of us, these worldly tangles are troubles we cannot simply shake off.'"), (9, None, "'Truly? Thank you so very much!'"), (10, None, "'Yet since you understand him so deeply, why did you leave him back then?'"), (11, None, '"I thought everyone had to speak in classical poetry around here! Let\'s hurry — I\'m rushing back to Shanghai!"')]
